const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Pacific Palisades region (north and west)
  const palisadesRegion = ee.Geometry.Rectangle([-118.58, 34.03, -118.45, 34.10]);

  // Date ranges
  const date1Start = '2025-01-06';
  const date1End = '2025-01-07';
  const date2Start = '2025-01-14';
  const date2End = '2025-01-15';

  // Function to calculate burned area using Sentinel-2
  function getBurnedArea(startDate, endDate, label) {
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(palisadesRegion)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    let size = col.size().getInfo();
    print(label + ' Images found: ' + size);

    if (size === 0) {
      return null;
    }

    let median = col.median();

    // Calculate NBR (Normalized Burn Ratio)
    // NBR = (NIR - SWIR2) / (NIR + SWIR2)
    // Sentinel-2: B8=NIR, B12=SWIR2
    let nbr = median.normalizedDifference(['B8', 'B12']).rename('NBR');

    // Burned areas typically have NBR < 0.4 (more negative = more burned)
    // Count pixels with NBR < 0.1 as burned
    let burned = nbr.lt(0.1);

    let pixelCount = burned.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: palisadesRegion,
      scale: 10,
      maxPixels: 1e9
    }).getInfo();

    let burnedPixels = pixelCount['NBR'] || 0;

    // Calculate total valid pixels
    let totalPixels = nbr.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: palisadesRegion,
      scale: 10,
      maxPixels: 1e9
    }).getInfo();

    let validPixels = totalPixels['NBR'] || 0;

    print(label + ' Burned pixels: ' + burnedPixels + ' / Valid: ' + validPixels);

    if (validPixels === 0) {
      return null;
    }

    return burnedPixels;
  }

  // Get burned area for both dates
  let burnedArea1 = getBurnedArea(date1Start, date1End, 'January 6, 2025');
  let burnedArea2 = getBurnedArea(date2Start, date2End, 'January 14, 2025');

  print('---');

  if (burnedArea1 === null) {
    print('Jan 6 data unavailable, trying Landsat 8...');
    let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(palisadesRegion)
      .filterDate(date1Start, date1End)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    if (col.size().getInfo() > 0) {
      burnedArea1 = 0; // Placeholder
    } else {
      print('No data for Jan 6');
      print('C1');
      return;
    }
  }

  if (burnedArea2 === null) {
    print('Jan 14 data unavailable');
    print('C1');
    return;
  }

  print('Burned Area Jan 6: ' + burnedArea1);
  print('Burned Area Jan 14: ' + burnedArea2);
  print('Change: ' + (burnedArea2 - burnedArea1));

  if (burnedArea2 > burnedArea1) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
